<script>
    import { onMount } from 'svelte';
    import { round } from '$lib/utils/helper';
    import { getTeamFromTeamManagers } from '$lib/utils/helperFunctions/universalFunctions';
    import { matchupInjurySentence } from './injuryStoryUtils.js';

    export let matchupArray = [];
    export let players = {};
    export let displayWeek;
    export let year;
    export let leagueTeamManagers;

    let playerSpotlightLabel = 'Player Of The Night';
    let liveInjuries = {};

    const liveStarterIds = () => [...new Set((matchupArray || []).flatMap((matchup) => (matchup || []).flatMap((entry) => entry?.starters || [])).filter((id) => id && id != 0).map(String))];
    const refreshInjuries = async () => { try { const ids = liveStarterIds(); const query = ids.length ? `&ids=${encodeURIComponent(ids.join(','))}` : ''; const res = await fetch(`/api/player_injuries?t=${Date.now()}${query}`, { cache: 'no-store' }); if (res.ok) liveInjuries = await res.json(); } catch (error) {} };
    onMount(() => { const updateLabel = () => { const now = new Date(); playerSpotlightLabel = now.getDay() === 0 && now.getHours() >= 9 && now.getHours() < 17 ? 'Player Of The Day' : 'Player Of The Night'; }; updateLabel(); refreshInjuries(); const labelTimer = setInterval(updateLabel, 60000); const injuryTimer = setInterval(refreshInjuries, 120000); return () => { clearInterval(labelTimer); clearInterval(injuryTimer); }; });
    $: newsroomPlayers = (() => { const merged = { ...players }; for (const [id, injury] of Object.entries(liveInjuries || {})) merged[id] = { ...(players?.[id] || {}), ...injury }; return merged; })();
    const numericRound = (value) => Number(round(Number(value) || 0));
    const sum = (values = []) => values.reduce((total, value) => total + (Number(value) || 0), 0);
    const actual = (entry) => numericRound(sum(entry?.points || []));
    const safeTeam = (id) => { try { return getTeamFromTeamManagers(leagueTeamManagers, Number(id), year) || { name: `Team ${id}` }; } catch (error) { return { name: `Team ${id}` }; } };
    const projection = (entry) => numericRound((entry?.starters || []).reduce((total, id) => { const value = Number(players?.[id]?.wi?.[displayWeek]?.p); return total + (Number.isFinite(value) ? value : 0); }, 0));
    const playerName = (id) => { const player = players?.[id]; if (!player) return `Player ${id}`; if (player.pos === 'DEF') return player.ln || player.fn || String(id).toUpperCase(); return `${player.fn || ''} ${player.ln || ''}`.trim() || `Player ${id}`; };
    const starterPerformances = (entry) => { const starters = entry?.starters || [], points = entry?.points || []; return starters.map((id, index) => { if (!id || id == 0) return null; const scored = Number(points[index] || 0), projected = Number(players?.[id]?.wi?.[displayWeek]?.p) || 0; return { id, name: playerName(id), points: numericRound(scored), projection: numericRound(projected), delta: numericRound(scored - projected) }; }).filter(Boolean); };
    const topScorer = (entry) => [...starterPerformances(entry)].sort((a,b) => b.points-a.points)[0] || null;
    const bestPerformance = (entry) => [...starterPerformances(entry)].filter(p=>p.points>0).sort((a,b)=>b.delta-a.delta||b.points-a.points)[0] || null;
    const biggestDisappointment = (entry) => [...starterPerformances(entry)].filter(p=>p.projection>=8).sort((a,b)=>a.delta-b.delta)[0] || null;
    const performanceSentence = (entry, teamName) => { const best=bestPerformance(entry), cold=biggestDisappointment(entry), parts=[]; if(best&&best.delta>=5) parts.push(`${best.name} is detonating the projection with ${best.points} points, already ${numericRound(best.delta)} above expectations and giving ${teamName} a jolt`); else if(best&&best.points>=12) parts.push(`${best.name} is dragging ${teamName} forward with ${best.points} points and has become the engine of this matchup`); if(cold&&cold.points>0&&cold.delta<=-8) parts.push(`${cold.name} is becoming a problem, sitting ${numericRound(Math.abs(cold.delta))} below projection and leaving valuable points on the table`); return parts.length?`${parts.join(', while ')}.`:''; };
    const matchupVariant = (a, b) => (Number(a?.roster_id || 0) * 7 + Number(b?.roster_id || 0) * 11 + Number(displayWeek || 0)) % 4;
    const upsetSentence = (a,b,leader,favorite,margin,projectedMargin,isEarly) => {
        const variants = [
            `${leader.team.name} has ripped up the pregame script. The ${projectedMargin}-point underdog now owns a ${margin}-point lead over ${favorite.team.name}${isEarly?', and the favorite is already feeling the pressure':', with the upset sirens getting louder by the minute'}.`,
            `${leader.team.name} came in as the underdog and apparently took that personally. A ${margin}-point advantage has ${favorite.team.name} chasing the game, and the ${projectedMargin}-point favorite suddenly has a real fight on its hands.`,
            `The favorite is in trouble. ${leader.team.name} has jumped ${favorite.team.name} and built a ${margin}-point lead despite entering the week ${projectedMargin} points behind in the projection. What looked comfortable before kickoff is anything but comfortable now.`,
            `${leader.team.name} is crashing the party. The projected underdog has stormed ahead by ${margin}, leaving ${favorite.team.name} staring at the scoreboard and wondering how quickly this matchup got away from the script.`
        ];
        return variants[matchupVariant(a,b)];
    };
    const buildNarrative = (a,b,one,two,leader,trailer,favorite,margin,projectedMargin,isUpset,top) => { let tag='📈 EARLY EDGE',tone='normal';const paragraphs=[],total=one.score+two.score,isEarly=total<35;if(!leader){tag='⚔️ DEAD EVEN';tone='close';paragraphs.push(`${one.team.name} and ${two.team.name} are locked in a dead heat. Neither side has blinked, and this matchup is sitting on a knife's edge waiting for one player to swing the entire night.`);}else if(isUpset){tag='🚨 UPSET BREWING';tone='upset';paragraphs.push(upsetSentence(a,b,leader,favorite,margin,projectedMargin,isEarly));}else if(margin>=30){tag='💥 BLOWOUT DEVELOPING';tone='blowout';paragraphs.push(`${leader.team.name} is turning this into a demolition. The lead has exploded to ${margin}, and ${trailer.team.name} is running out of room to stop this from becoming the week's ugliest result.`);}else if(margin<=5){tag='😬 LEAD IN DANGER';tone='close';paragraphs.push(`${leader.team.name} is hanging onto the lead by a thread. Only ${margin} points separate these teams, and one touchdown, one long catch, or one busted projection could flip the entire matchup in seconds.`);}else if(favorite===trailer&&margin>=8){tag='🔥 COMEBACK WATCH';tone='comeback';paragraphs.push(`${trailer.team.name} came in as the projected favorite, but now the night is turning into survival mode. It trails ${leader.team.name} by ${margin}, and every remaining starter suddenly carries comeback pressure.`);}else if(margin>=20){tag='🔥 TAKING CONTROL';tone='hot';paragraphs.push(`${leader.team.name} is starting to put a boot on this matchup. The advantage has climbed to ${margin}, forcing ${trailer.team.name} to chase a major swing before this gets away for good.`);}else paragraphs.push(`${leader.team.name} has seized a ${margin}-point advantage over ${trailer.team.name}. ${favorite===leader?'The favorite is doing what it was supposed to do, but the door is still cracked open.':'That is a direct shot at the pregame projection, and the favorite is now the one scrambling to answer.'}`);const leaderEntry=leader===one?a:b,trailerEntry=leader===one?b:a;if(leader){const lp=performanceSentence(leaderEntry,leader.team.name),tp=performanceSentence(trailerEntry,trailer.team.name);if(lp)paragraphs.push(lp);else if(top?.points>0)paragraphs.push(`${top.name} is setting the tone with ${top.points} points and is currently the biggest reason this matchup has tilted.`);if(tp)paragraphs.push(tp);}else if(top?.points>0)paragraphs.push(`${top.name} leads all starters with ${top.points} points, but even that has not been enough to break the stalemate.`);const injuryText=matchupInjurySentence(a,b,newsroomPlayers,displayWeek,one.team.name,two.team.name,'live').trim();if(injuryText)paragraphs.push(injuryText);if(leader&&margin<=10)paragraphs.push(`This one is nowhere near safe. ${leader.team.name} has the scoreboard edge, but ${trailer.team.name} is still one explosive performance away from ripping the lead away.`);else if(leader&&margin>=20)paragraphs.push(`${trailer.team.name} now needs something dramatic from the players still to come. Meanwhile, ${leader.team.name} can start thinking about slamming the door shut.`);return{tag,tone,text:paragraphs.join(' ')};};
    const makeUpdate=(matchup)=>{const a=matchup?.[0],b=matchup?.[1];if(!a||!b)return null;const one={team:safeTeam(a.roster_id),score:actual(a),projection:projection(a)},two={team:safeTeam(b.roster_id),score:actual(b),projection:projection(b)},topA=topScorer(a),topB=topScorer(b),top=!topA?topB:!topB?topA:topA.points>=topB.points?topA:topB,leader=one.score===two.score?null:one.score>two.score?one:two,trailer=leader===one?two:one,favorite=one.projection===two.projection?null:one.projection>two.projection?one:two,margin=numericRound(Math.abs(one.score-two.score)),projectedMargin=numericRound(Math.abs(one.projection-two.projection)),isUpset=leader&&favorite&&leader!==favorite&&projectedMargin>=3,narrative=buildNarrative(a,b,one,two,leader,trailer,favorite,margin,projectedMargin,isUpset,top);return{teamOne:one.team,teamTwo:two.team,scoreOne:one.score,scoreTwo:two.score,projectionOne:one.projection,projectionTwo:two.projection,top,tag:narrative.tag,tone:narrative.tone,text:narrative.text,margin,leader,trailer,favorite,total:one.score+two.score};};
    $: updates=(matchupArray||[]).map(makeUpdate).filter(Boolean);$: highest=updates.flatMap(i=>[{team:i.teamOne,points:i.scoreOne},{team:i.teamTwo,points:i.scoreTwo}]).sort((a,b)=>b.points-a.points)[0];$: closest=[...updates].sort((a,b)=>a.margin-b.margin)[0];$: topPlayer=updates.map(i=>i.top).filter(Boolean).sort((a,b)=>b.points-a.points)[0];$: upset=updates.find(i=>i.tone==='upset');
    $: liveStories=(()=>{const s=[];if(upset)s.push({label:'🚨 Upset Brewing',text:`${upset.leader.team.name} has the favorite on the ropes. ${upset.favorite.team.name} was supposed to control this matchup, but now it is chasing the scoreboard and one more big swing could turn this into Week ${displayWeek}'s headline upset.`});const blow=[...updates].filter(i=>i.margin>=30).sort((a,b)=>b.margin-a.margin)[0];if(blow)s.push({label:'💥 Blowout Developing',text:`${blow.leader.team.name} is delivering the week's biggest beatdown at ${blow.margin} points. ${blow.trailer.team.name} needs a miracle-sized response before this turns into a full-on humiliation.`});const comeback=updates.find(i=>i.favorite&&i.leader&&i.favorite!==i.leader&&i.margin>=8);if(comeback)s.push({label:'🔥 Comeback Watch',text:`${comeback.favorite.team.name} was expected to be in control, but now the favorite is staring at a ${comeback.margin}-point hole. Every remaining starter is suddenly part of a comeback attempt.`});if(closest&&closest.margin<=7)s.push({label:'👀 One to Watch',text:`${closest.teamOne.name} and ${closest.teamTwo.name} are separated by only ${closest.margin}. This is the matchup where one touchdown could change everything instantly.`});if(topPlayer&&topPlayer.projection>0&&topPlayer.points>=topPlayer.projection+10)s.push({label:'🏆 Statement Performance',text:`${topPlayer.name} is wrecking expectations with ${topPlayer.points}, already ${numericRound(topPlayer.points-topPlayer.projection)} above projection and single-handedly reshaping the matchup.`});return s.slice(0,4);})();
    $: liveVerdict=(()=>{if(!updates.length)return'';const s=[];if(highest)s.push(`${highest.team.name} is setting the league's scoring pace at ${highest.points} and forcing everyone else to chase`);if(upset)s.push(`${upset.leader.team.name} has projected favorite ${upset.favorite.team.name} in real upset danger`);if(closest&&closest.margin<=7)s.push(`${closest.teamOne.name} vs ${closest.teamTwo.name} is hanging by a thread with almost no margin for error`);return s.length?`Week ${displayWeek} is starting to get loud: ${s.join('; ')}. The scoreboard can still turn, but right now these are the pressure points threatening to define the entire week.`:`Week ${displayWeek} is still waiting for somebody to seize the spotlight, but the board is starting to tighten.`;})();
</script>

<style>
.liveCard{width:95%;max-width:900px;margin:0 auto 24px;padding:20px;box-sizing:border-box;border:1px solid var(--ccc);border-radius:16px;background:var(--fff);box-shadow:0 4px 14px rgba(0,0,0,.06)}.header{text-align:center;margin-bottom:16px}.eyebrow{font-size:.72rem;font-weight:800;letter-spacing:1px;text-transform:uppercase;opacity:.72}h4{margin:5px 0 0;font-size:1.35rem}.sub{margin-top:5px;font-size:.7rem;opacity:.62}.summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-bottom:16px}.summaryItem,.story,.game{padding:12px;border-radius:12px;background:var(--f3f3f3)}.label{font-size:.65rem;font-weight:800;text-transform:uppercase;letter-spacing:.4px;opacity:.72}.value{margin-top:4px;font-size:.86rem;font-weight:850}.stories,.games{display:grid;gap:10px}.stories{margin-bottom:16px}.storyText{margin-top:5px;font-size:.78rem;line-height:1.55;font-weight:600}.analysisTag{margin-bottom:9px;text-align:center;font-size:.68rem;font-weight:900;letter-spacing:.65px;opacity:1}.scoreLine{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:8px;font-weight:900}.teamOne{text-align:right}.teamTwo{text-align:left}.score{white-space:nowrap;font-size:1.08rem}.projections{margin-top:5px;text-align:center;font-size:.67rem;opacity:.7}.note{margin-top:11px;text-align:left;font-size:.8rem;line-height:1.6}.verdict{margin-top:16px;padding:15px;border:1px solid var(--ccc);border-radius:12px}.verdictTitle{font-size:.72rem;font-weight:900;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px}.verdictText{font-size:.82rem;line-height:1.55;font-weight:600}@media(max-width:600px){.liveCard{width:100%;padding:15px 12px}.scoreLine{font-size:.82rem}.score{font-size:1rem}.note,.storyText{font-size:.74rem}}
</style>

{#if updates.length}<section class="liveCard"><div class="header"><div class="eyebrow">Live Week {displayWeek} Newsroom</div><h4>📰 GGL Live Desk</h4><div class="sub">The story changes as the Sleeper scoreboard changes</div></div><div class="summary"><div class="summaryItem"><div class="label">🔥 Hot Start</div><div class="value">{highest?.team?.name||'—'} · {highest?.points??0}</div></div><div class="summaryItem"><div class="label">⚔️ Game To Watch</div><div class="value">{closest?`${closest.teamOne.name} vs ${closest.teamTwo.name}`:'—'}</div></div><div class="summaryItem"><div class="label">⭐ {playerSpotlightLabel}</div><div class="value">{topPlayer?`${topPlayer.name} · ${topPlayer.points}`:'—'}</div></div><div class="summaryItem"><div class="label">🚨 Upset Watch</div><div class="value">{upset?`${upset.leader.team.name} over ${upset.favorite.team.name}`:'None yet'}</div></div></div>{#if liveStories.length}<div class="stories">{#each liveStories as story}<div class="story"><div class="label">{story.label}</div><div class="storyText">{story.text}</div></div>{/each}</div>{/if}<div class="games">{#each updates as item}<div class="game"><div class="analysisTag">{item.tag}</div><div class="scoreLine"><div class="teamOne">{item.teamOne.name}</div><div class="score">{item.scoreOne} – {item.scoreTwo}</div><div class="teamTwo">{item.teamTwo.name}</div></div><div class="projections">Pregame projection: {item.projectionOne} – {item.projectionTwo}</div><div class="note">{item.text}</div></div>{/each}</div>{#if liveVerdict}<div class="verdict"><div class="verdictTitle">📰 Live Newsroom Pulse</div><div class="verdictText">{liveVerdict}</div></div>{/if}</section>{/if}